using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using MyFundex.BuildingBlocks.Abstractions;using MyFundex.BuildingBlocks.Domain;using MyFundex.BuildingBlocks.Persistence;
namespace MyFundex.Payments;
public sealed class PaymentTransaction:EntityBase{public Guid PaymentId{get;set;}public long UserInternalId{get;set;}public Guid? SubscriptionId{get;set;}public string Provider{get;set;}="";public string? ProviderPaymentId{get;set;}public decimal Amount{get;set;}public string CurrencyCode{get;set;}="INR";public string Status{get;set;}="Pending";public string Purpose{get;set;}="Subscription";public DateTimeOffset? PaidAt{get;set;}public string? FailureReason{get;set;}}
public sealed class Invoice:EntityBase{public Guid InvoiceId{get;set;}public long PaymentInternalId{get;set;}public string InvoiceNumber{get;set;}="";public decimal TaxableAmount{get;set;}public decimal TaxAmount{get;set;}public decimal GrossAmount{get;set;}public string? StorageKey{get;set;}}
public sealed class Receipt:EntityBase{public Guid ReceiptId{get;set;}public long PaymentInternalId{get;set;}public string ReceiptNumber{get;set;}="";public string? StorageKey{get;set;}}
public sealed class PaymentsDbContext(DbContextOptions<PaymentsDbContext>o,ICurrentActor a):AuditableDbContext(o,a){public DbSet<PaymentTransaction>Payments=>Set<PaymentTransaction>();public DbSet<Invoice>Invoices=>Set<Invoice>();public DbSet<Receipt>Receipts=>Set<Receipt>();protected override void OnModelCreating(ModelBuilder m){m.HasDefaultSchema("payments");ConfigureEntity(m.Entity<PaymentTransaction>());ConfigureEntity(m.Entity<Invoice>());ConfigureEntity(m.Entity<Receipt>());m.Entity<PaymentTransaction>().HasIndex(x=>x.PaymentId).IsUnique();m.Entity<PaymentTransaction>().Property(x=>x.Amount).HasPrecision(20,4);}}
public static class PaymentsModule{public static IServiceCollection AddPaymentsModule(this IServiceCollection s,string cs){s.AddDbContext<PaymentsDbContext>(o=>o.UseNpgsql(cs));return s;}}
